  ('C-079', 'PK-C', 'MM-03', 'Vòng 6 - Cung C2 - Ô 10', 'Đã an táng', 3.3, 4.13, 252.19, ST_GeomFromText('POLYGON Z((35.322 -8.753 4.04, 34.649 -10.848 3.93, 36.078 -11.307 3.93, 36.751 -9.212 4.03, 35.322 -8.753 4.04))', 3405)),
  ('C-080', 'PK-C', 'MM-03', 'Vòng 6 - Cung C2 - Ô 11', 'Đã an táng', 3.3, 4.21, 247.73, ST_GeomFromText('POLYGON Z((34.423 -5.988 4.13, 33.589 -8.024 4.04, 34.977 -8.592 4.04, 35.811 -6.556 4.13, 34.423 -5.988 4.13))', 3405))
)
SELECT
  r.ma_lo_dat, r.ma_phan_khu, r.ma_mau_mo, r.vi_tri_hang_o,
  CASE
    WHEN cfg.use_code AND r.trang_thai_vn = 'Đã an táng' THEN 'DA_AN_TANG'
    WHEN cfg.use_code AND r.trang_thai_vn = 'Đã đặt trước' THEN 'DA_DAT_TRUOC'
    WHEN cfg.use_code AND r.trang_thai_vn = 'Trống' THEN 'TRONG'
    ELSE r.trang_thai_vn
  END,
  r.dien_tich_lo, r.cao_do_z, r.goc_xoay_z, r.geom_3d
FROM raw_lots r CROSS JOIN cfg;

-- 6. Hồ sơ Người mất (171 hồ sơ)

