      AND pg_get_constraintdef(oid) LIKE '%KE_NHAU_LODAT%'
  ) AS use_vn_code
),
raw_topo(ma_lo_dat_goc, ma_lo_dat_ke_can, ma_ha_tang_tiep_giap, ma_duong_tiep_giap, loai_quan_he, khoang_cach_3d, hop_le_quy_hoach) AS (
